57	    /** Add a person to the sheet with their own terms (null for none); the grade they are given
58	     *  applies from the beginning of time. */
59	    @Transactional
60	    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
61	        LocalDate today = sheets.today(sheetId);
62	        String trimmed = name.trim();
63	        requireFreeName(sheetId, trimmed, null);
64	        Person person = new Person(sheetId, trimmed, today);
65	        person.setTerms(terms);
66	        Person added = people.saveAndFlush(person);
67	        grades.give(added, grade, null);
68	        record("PERSON_ADDED", sheetId, user, added, grade, terms != null ? " terms=" + terms : "");
69	        return added;
70	    }
