72	    /** Change a person's name, and give them the grade from a date (blank takes the sheet's today),
73	     *  keeping the grades already given, and set their own terms (null for none), from an editor that loaded the given version of them. A
74	     *  blank from-date with the grade in force on the sheet's today gives no grade. */
75	    @Transactional
76	    public Person update(String sheetId, String user, Long id, long version, String name, String grade,
77	            LocalDate gradeFrom, Integer terms) {
78	        Person person = people.findByIdAndSheetId(id, sheetId)
79	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
80	        if (person.getVersion() != version) {
81	            throw new StalePersonException(person);
82	        }
83	        String trimmed = name.trim();
84	        requireFreeName(sheetId, trimmed, id);
85	        person.setName(trimmed);
86	        Integer before = person.getTerms();
87	        person.setTerms(terms);
88	        LocalDate today = sheets.today(sheetId);
89	        if (gradeFrom != null || !grade.equals(grades.gradeOn(id, today))) {
90	            grades.give(person, grade, gradeFrom != null ? gradeFrom : today);
91	            // A grade given changes the person, so an editor that loaded them before is stale.
92	            entityManager.lock(person, LockModeType.PESSIMISTIC_FORCE_INCREMENT);
93	        }
94	        Person saved = people.saveAndFlush(person);
95	        record("PERSON_EDITED", sheetId, user, saved, grades.gradeOn(id, today),
96	                Objects.equals(before, terms) ? "" : " terms=" + (terms != null ? terms : ""));
97	        return saved;
98	    }
99	
100	    /** Retire a person from a date; a missing date takes the sheet's today. */
101	    @Transactional
102	    public Person retire(String sheetId, String user, Long id, LocalDate from) {
103	        Person person = people.findByIdAndSheetId(id, sheetId)
104	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
105	        LocalDate on = from != null ? from : sheets.today(sheetId);
106	        person.setRetiredFrom(on);
107	        Person saved = people.saveAndFlush(person);
108	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
109	                + " from=" + on);
110	        return saved;
111	    }
112	
113	    /** Put a hold on a person from a date (a missing date takes the sheet's today) to an optional
114	     *  to-date, keeping the holds they have; refused when the to-date is before the from-date. */
115	    @Transactional
116	    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
117	        Person person = people.findByIdAndSheetId(id, sheetId)
118	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
119	        LocalDate on = from != null ? from : sheets.today(sheetId);
120	        if (to != null && to.isBefore(on)) {
121	            throw new HoldRefusedException("The hold's to-date " + to + " is before its from-date " + on);
122	        }
123	        holds.saveAndFlush(new PersonHold(sheetId, id, on, to, sheets.today(sheetId)));
124	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + person.getName()
125	                + " from=" + on);
126	        return person;
127	    }
