129	    /** Each person's holds on the sheet, in the order they were put on, by person id; a person with
130	     *  none is absent. */
131	    public Map<Long, List<PersonHold>> holds(String sheetId) {
132	        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
133	                .collect(Collectors.groupingBy(PersonHold::getPersonId));
134	    }
