141	    /** A person's holds as they stood at the end of a day: those put on while the sheet's today was
142	     *  on or before it, in the order they were put on. */
143	    public List<PersonHold> holdsAsOf(Long personId, LocalDate day) {
144	        return holds(personId).stream().filter(hold -> hold.madeAsOf(day)).toList();
145	    }
