147	    /** Each person's patron ids on the sheet, in the order they were named, by person id; a person
148	     *  with none is absent. */
149	    public Map<Long, List<Long>> patronIds(String sheetId) {
150	        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
151	                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
152	                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
153	    }
154	
155	    /** Each person's patron ids on the sheet as they stood at the end of a day, in the order they were
156	     *  named, by person id (null: as they stand now); a person with none is absent. */
157	    public Map<Long, List<Long>> patronIds(String sheetId, LocalDate asOf) {
158	        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
159	                .filter(patron -> asOf == null || patron.madeAsOf(asOf))
160	                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
161	                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
162	    }
163	
164	    /** Each person's holds on the sheet as they stood at the end of a day, in the order they were put
165	     *  on, by person id (null: as they stand now); a person with none is absent. */
166	    public Map<Long, List<PersonHold>> holds(String sheetId, LocalDate asOf) {
167	        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
168	                .filter(hold -> asOf == null || hold.madeAsOf(asOf))
169	                .collect(Collectors.groupingBy(PersonHold::getPersonId));
170	    }
171	
172	    /** The ids of the people a user watched on the sheet at the end of a day (null: now). */
173	    public Set<Long> watchedIds(String sheetId, String user, LocalDate asOf) {
174	        Set<Long> now = watchedIds(sheetId, user);
175	        return asOf == null ? now : history.watched(sheetId, user, now, asOf);
176	    }
177	
178	    /** The sheet's people as they stood at the end of a day, in the order they were added: those added
179	     *  by then, each with the name, own terms and retirement they had then (null: as they stand now). */
180	    public List<Person> list(String sheetId, LocalDate asOf) {
181	        if (asOf == null) {
182	            return list(sheetId);
183	        }
184	        Map<Long, History.PersonThen> then = history.people(sheetId, asOf);
185	        return list(sheetId).stream().filter(person -> person.onSheetAsOf(asOf)).map(person -> {
186	            History.PersonThen was = then.get(person.getId());
187	            return was == null ? person : person.asItWas(was.name(), was.terms(), was.retiredFrom());
188	        }).toList();
189	    }
190	
191	    /** A person's patron ids, in the order they were named. */
192	    public List<Long> patronIds(Long personId) {
193	        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
194	    }
195	
196	    /** Name another person on the sheet as a person's patron; refused for the person themselves and
197	     *  for someone already their patron. */
198	    @Transactional
199	    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
200	        Person person = people.findByIdAndSheetId(id, sheetId)
201	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
202	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
203	                .orElseThrow(() -> new NoSuchElementException("No person " + patronId + " on sheet " + sheetId));
204	        if (person.getId().equals(patron.getId())) {
205	            throw new PatronRefusedException(person.getName() + " cannot be their own patron");
206	        }
207	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
208	            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
209	        }
210	        patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId(), sheets.today(sheetId)));
211	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
212	                + " patron=" + patron.getName());
213	        return person;
214	    }
215	
216	    /** Start or stop a user watching a person; a person already in that state is left as they are,
217	     *  writing nothing. */
218	    @Transactional
219	    public Person watch(String sheetId, String user, Long id, boolean on) {
220	        Person person = people.findByIdAndSheetId(id, sheetId)
221	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
222	        var existing = watches.findByPersonIdAndUser(id, user);
223	        if (on && existing.isEmpty()) {
224	            watches.saveAndFlush(new PersonWatch(sheetId, id, user));
225	            history.watchSet(sheetId, id, user, true);
226	            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
227	        } else if (!on && existing.isPresent()) {
228	            watches.delete(existing.get());
229	            watches.flush();
230	            history.watchSet(sheetId, id, user, false);
231	            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
232	        }
233	        return person;
234	    }
235	
236	    /** The ids of the people a user watches on the sheet. */
237	    public Set<Long> watchedIds(String sheetId, String user) {
238	        return watches.findBySheetIdAndUser(sheetId, user).stream().map(PersonWatch::getPersonId)
239	                .collect(Collectors.toSet());
240	    }
241	
242	    /** Whether a user watches a person. */
243	    public boolean watches(Long personId, String user) {
244	        return watches.findByPersonIdAndUser(personId, user).isPresent();
245	    }
246	
247	    /** A person's watchers, in the order they started watching. */
248	    public List<String> watchers(Long personId) {
249	        return watches.findByPersonIdOrderByIdAsc(personId).stream().map(PersonWatch::getUser).toList();
250	    }
251	
252	    private void record(String event, String sheetId, String user, Person person, String grade, String terms) {
253	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
254	                + " name=" + person.getName() + " grade=" + grade + terms);
255	    }
256	
257	    private void requireFreeName(String sheetId, String name, Long exceptId) {
258	        if (people.nameInUse(sheetId, name, exceptId)) {
259	            throw new NameInUseException(name);
260	        }
261	    }
262	}
